struct DSU {
    std::vector<int> p, r;
    DSU(int n): p(n), r(n, 0) { for (int i = 0; i < n; ++i) p[i] = i; }
    int find(int x) { return p[x] == x ? x : p[x] = find(p[x]); }
    bool unite(int a, int b) { a = find(a); b = find(b); if (a == b) return false; if (r[a] < r[b]) std::swap(a, b); p[b] = a; if (r[a] == r[b]) ++r[a]; return true; }
};

int kruskal_mst(int n, std::vector<Edge> edges) {
    std::sort(edges.begin(), edges.end(), [](const Edge& a, const Edge& b){ return a.w < b.w; });
    DSU dsu(n);
    int total = 0, cnt = 0;
    for (const auto& e : edges) {
        if (dsu.unite(e.u, e.v)) { total += e.w; if (++cnt == n - 1) break; }
    }
    return (cnt == n - 1) ? total : -1;
}

