std::vector<int> kmp_search(const std::string& text, const std::string& pat) {
    int n = (int)text.size(), m = (int)pat.size();
    if (m == 0) return {};
    std::vector<int> lps(m, 0);
    for (int i = 1, len = 0; i < m; ) {
        if (pat[i] == pat[len]) lps[i++] = ++len;
        else if (len) len = lps[len - 1]; else lps[i++] = 0;
    }
    std::vector<int> res;
    for (int i = 0, j = 0; i < n; ) {
        if (text[i] == pat[j]) { ++i; ++j; if (j == m) { res.push_back(i - m); j = lps[j - 1]; } }
        else if (j) j = lps[j - 1]; else ++i;
    }
    return res;
}

