class Fenwick {
  int n;
  std::vector<long long> bit; // 1-indexed
public:
  explicit Fenwick(int n_): n(n_), bit(n+1, 0) {}
  explicit Fenwick(const std::vector<long long>& a): n((int)a.size()), bit(n+1, 0) {
    for (int i = 1; i <= n; ++i) add(i, a[i-1]);
  }
  void add(int idx, long long delta) {
    for (; idx <= n; idx += idx & -idx) bit[idx] += delta;
  }
  long long sum(int idx) const {
    long long r = 0;
    for (; idx > 0; idx -= idx & -idx) r += bit[idx];
    return r;
  }
  long long rangeSum(int l, int r) const {
    if (r < l) return 0;
    return sum(r) - sum(l - 1);
  }
};

