  std::vector<long long> t;
public:
  explicit SegTree(int n_) {
    n = 1;
    while (n < n_) n <<= 1;
    t.assign(2 * n, 0);
  }
  explicit SegTree(const std::vector<long long>& a): SegTree((int)a.size()) {
    for (int i = 0; i < (int)a.size(); ++i) t[n + i] = a[i];
    for (int i = n - 1; i > 0; --i) t[i] = t[i << 1] + t[i << 1 | 1];
  }
  void pointUpdate(int i, long long val) {
    int p = n + i;
    t[p] = val;
    for (p >>= 1; p > 0; p >>= 1) t[p] = t[p << 1] + t[p << 1 | 1];
  }
  long long rangeSum(int l, int r) const {
    long long res = 0;
    for (l += n, r += n; l <= r; l >>= 1, r >>= 1) {
      if (l & 1) res += t[l++];
      if (!(r & 1)) res += t[r--];
    }
    return res;
  }
};

#include <unordered_map>
#include <list>
#include <utility>

class LRUCache {
  int cap;
  std::list<std::pair<int,int>> lst; // front: most recent
  std::unordered_map<int, std::list<std::pair<int,int>>::iterator> mp;
  void touch(std::unordered_map<int, std::list<std::pair<int,int>>::iterator>::iterator it) {
    int k = it->first;
    auto node = it->second;
    int v = node->second;
    lst.erase(node);
    lst.push_front({k, v});
    it->second = lst.begin();
  }
public:
  explicit LRUCache(int capacity): cap(capacity) {}
  int get(int key) {
    auto it = mp.find(key);
    if (it == mp.end()) return -1;
    touch(it);
    return it->second->second;
  }
  void put(int key, int value) {
    auto it = mp.find(key);
    if (it != mp.end()) {
      it->second->second = value;
      touch(it);
      return;
    }
    if ((int)lst.size() == cap) {
      auto back = lst.back();
      mp.erase(back.first);
      lst.pop_back();
    }
    lst.push_front({key, value});
    mp[key] = lst.begin();
  }
};

#include <vector>
#include <cstdint>

std::vector<uint8_t> modbus_crc16_le(const std::vector<uint8_t>& data) {
    uint16_t crc = 0xFFFFu;
    for (uint8_t b : data) {
        crc ^= b;
        for (int i = 0; i < 8; ++i) {
            if (crc & 1u) crc = (crc >> 1) ^ 0xA001u;
            else crc >>= 1;
        }
    }
    return { static_cast<uint8_t>(crc & 0xFFu), static_cast<uint8_t>(crc >> 8) };
}

#include <vector>
#include <cstdint>

std::vector<uint8_t> crc32_ieee_be(const std::vector<uint8_t>& data) {
    uint32_t crc = 0xFFFFFFFFu;
    for (uint8_t b : data) {
        crc ^= b;
        for (int i = 0; i < 8; ++i) {
            if (crc & 1u) crc = (crc >> 1) ^ 0xEDB88320u;
            else crc >>= 1;
        }
    }
    crc ^= 0xFFFFFFFFu;
    return {
        static_cast<uint8_t>((crc >> 24) & 0xFFu),
        static_cast<uint8_t>((crc >> 16) & 0xFFu),
        static_cast<uint8_t>((crc >> 8) & 0xFFu),
        static_cast<uint8_t>(crc & 0xFFu)
    };
}

#include <vector>
#include <cstdint>

uint8_t checksum_sum8(const std::vector<uint8_t>& data) {
    uint32_t s = 0;
    for (uint8_t b : data) s += b;
    return static_cast<uint8_t>(s & 0xFFu);
}

#include <vector>
#include <cstdint>

uint8_t lrc8(const std::vector<uint8_t>& data) {
    uint32_t s = 0;
    for (uint8_t b : data) s += b;
    return static_cast<uint8_t>((-static_cast<int32_t>(s)) & 0xFF);
}

#include <vector>
#include <cstdint>

uint8_t checksum_xor(const std::vector<uint8_t>& data) {
    uint8_t x = 0;
    for (uint8_t b : data) x ^= b;
    return x;
}

#include <cstdint>

uint8_t parity_bit(uint8_t b, bool odd) {
    int ones = 0;
    for (int i = 0; i < 8; ++i) if ((b >> i) & 1u) ++ones;
    if (odd) return static_cast<uint8_t>((ones & 1) ^ 1);
    return static_cast<uint8_t>(ones & 1);
}
